package net.sf.saxon.pattern;

import net.sf.saxon.om.GNode;
import net.sf.saxon.om.NodeName;
import net.sf.saxon.pattern.qname.QNameTest;
import net.sf.saxon.type.ItemType;
import net.sf.saxon.type.SchemaType;
import net.sf.saxon.type.UType;

/**
 * A RawNodeTest is generated by the XPath parser for a node test in an axis step, before
 * any type information is available. It is designed to capture the syntax of what is
 * written in the source XPath, but does not itself have the logic for matching the
 * node test. The node test is elaborated (or cooked) into one that does have this logic
 * either during type checking, when static type information might be available, or
 * if all else fails at evaluation time.
 */

public abstract class RawNodeTest extends NodeTest {

    /**
     * Convert this RawNodeTest to an executable node test using type information
     * about the origin node of the axis step.
     * @param origin the type of the origin node
     * @return a refined NodeTest.
     */
    public abstract NodeTest cook(ItemType origin);

    /**
     * Convert this RawNodeTest to an executable node test knowing the
     * actual origin node. This method can take advantage of the actual
     * tree model used, e.g. if the origin is a node in a TinyTree.
     *
     * @param origin the origin node
     * @return a refined NodeTest.
     */
    public abstract NodePredicate cook(GNode origin);

    /**
     * Determine the default priority to use if this node-test appears as a match pattern
     * for a template with no explicit priority attribute.
     *
     * @return the default priority for the pattern
     */
    @Override
    public double getDefaultPriority() {
        return 0;
    }

    /**
     * Extract a QNameTest (the strongest one possible) that must be satisfied by a node
     * if it is to satisfy this NodeTest
     *
     * @return the strongest possible QNameTest
     */
    @Override
    public QNameTest getQNameTest() {
        return null;
    }

    /**
     * Test whether this node test is satisfied by a given node. This method is only
     * fully supported for a subset of NodeTests, because it doesn't provide all the information
     * needed to evaluate all node tests. In particular (a) it can't be used to evaluate a node
     * test of the form element(N,T) or schema-element(E) where it is necessary to know whether the
     * node is nilled, and (b) it can't be used to evaluate a node test of the form
     * document-node(element(X)). This in practice means that it is used (a) to evaluate the
     * simple node tests found in the XPath 1.0 subset used in XML Schema, and (b) to evaluate
     * node tests where the node kind is known to be an attribute.
     *
     * @param nodeKind   The kind of node to be matched
     * @param name       identifies the expanded name of the node to be matched.
     *                   The value should be null for a node with no name.
     * @param annotation The actual content type of the node. Null means no constraint.
     * @return true if the node matches this node test
     */
    @Override
    public boolean matches(int nodeKind, NodeName name, SchemaType annotation) {
        return false;
    }

    /**
     * Get the corresponding {@link UType}. A UType is a union of primitive item
     * types.
     *
     * @return the smallest UType that subsumes this item type
     */
    @Override
    public UType getUType() {
        return UType.XNODE;
    }

    /**
     * Get the default priority normalized into the range 0 to 1
     *
     * @return the default priority plus one divided by two
     */
    @Override
    public double getNormalizedDefaultPriority() {
        return super.getNormalizedDefaultPriority();
    }

    /**
     * Get the full alpha code for this item type. As well as the basic alpha code, this contains
     * additional information, for example <code>element(EFG)</code> has a basic alpha code of
     * <code>NE</code>, but the full alpha code of <code>NE nQ{}EFG</code>.
     *
     * @return the alpha code for the type
     */
    @Override
    public String getFullAlphaCode() {
        return super.getFullAlphaCode();
    }

    /**
     * Return a string representation of this ItemType suitable for use in stylesheet
     * export files. This differs from the result of toString() in that it will not contain
     * any references to anonymous types. Note that it may also use the Saxon extended syntax
     * for union types and tuple types. The default implementation returns the result of
     * calling {@code toString()}.
     *
     * @return the string representation as an instance of the XPath SequenceType construct
     */
    @Override
    public String toExportString() {
        return super.toExportString();
    }
}

